@Test
public void testPqlAndSqlCompatible() throws Exception {
    final BufferedReader brPql = new BufferedReader(new InputStreamReader(PqlAndCalciteSqlCompatibilityTest.class.getClassLoader().getResourceAsStream("pql_queries.list")));
    final BufferedReader brSql = new BufferedReader(new InputStreamReader(PqlAndCalciteSqlCompatibilityTest.class.getClassLoader().getResourceAsStream("sql_queries.list")));
    String sql;
    int seqId = 0;
    while ((sql = brSql.readLine()) != null) {
        final String pql = brPql.readLine();
        try {
            // PQL
            LOGGER.info("Trying to compile PQL Id - {}, PQL: {}", seqId, pql);
            final BrokerRequest brokerRequestFromPQL = OPTIMIZER.optimize(COMPILER.compileToBrokerRequest(pql), null);
            LOGGER.debug("Compiled PQL: Id - {}, PQL: {}, BrokerRequest: {}", seqId, pql, brokerRequestFromPQL);
            brokerRequestFromPQL.unsetPinotQuery();
            //SQL
            LOGGER.info("Trying to compile SQL Id - {}, SQL: {}", seqId, sql);
            final PinotQuery pinotQuery = CalciteSqlParser.compileToPinotQuery(sql);
            final BrokerRequest brokerRequestFromSQL = OPTIMIZER.optimize(new PinotQuery2BrokerRequestConverter().convert(pinotQuery), null);
            LOGGER.debug("Compiled SQL: Id - {}, SQL: {}, PinotQuery: {}, BrokerRequest: {}", seqId, sql, pinotQuery, brokerRequestFromSQL);
            // Compare
            LOGGER.info("Trying to compare BrokerRequest - Id: {}\nFrom PQL: {}\nFrom SQL: {}", seqId, brokerRequestFromPQL, brokerRequestFromSQL);
            Assert.assertTrue(BrokerRequestComparisonUtils.validate(brokerRequestFromPQL, brokerRequestFromSQL));
            seqId++;
        } catch (Exception e) {
            LOGGER.error("Failed to compare results from \n\tPQL: {}\nand\n\tSQL: {}", pql, sql, e);
            throw e;
        }
    }
}

@Test
public void testSetOptions() {
    Pql2Compiler compiler = new Pql2Compiler();
    BrokerRequest brokerRequest;
    ObjectNode jsonRequest;
    int requestId = 1;
    String query = "select * from table";
    // none of the options
    jsonRequest = JsonUtils.newObjectNode();
    brokerRequest = compiler.compileToBrokerRequest(query);
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertFalse(brokerRequest.isEnableTrace());
    Assert.assertNull(brokerRequest.getDebugOptions());
    Assert.assertEquals(brokerRequest.getQueryOptionsSize(), 0);
    // TRACE
    // has trace false
    jsonRequest.put(Request.TRACE, false);
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertFalse(brokerRequest.isEnableTrace());
    Assert.assertNull(brokerRequest.getDebugOptions());
    Assert.assertEquals(brokerRequest.getQueryOptionsSize(), 0);
    // has trace true
    jsonRequest.put(Request.TRACE, true);
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertTrue(brokerRequest.isEnableTrace());
    // DEBUG_OPTIONS
    // has debugOptions
    jsonRequest.put(Request.DEBUG_OPTIONS, "debugOption1=foo");
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertEquals(brokerRequest.getDebugOptionsSize(), 1);
    Assert.assertEquals(brokerRequest.getDebugOptions().get("debugOption1"), "foo");
    // has multiple debugOptions
    jsonRequest.put(Request.DEBUG_OPTIONS, "debugOption1=foo;debugOption2=bar");
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertEquals(brokerRequest.getDebugOptionsSize(), 2);
    Assert.assertEquals(brokerRequest.getDebugOptions().get("debugOption1"), "foo");
    Assert.assertEquals(brokerRequest.getDebugOptions().get("debugOption2"), "bar");
    // incorrect debug options
    boolean exception = false;
    jsonRequest.put(Request.DEBUG_OPTIONS, "debugOption1");
    try {
        BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    } catch (Exception e) {
        exception = true;
    }
    Assert.assertTrue(exception);
    // QUERY_OPTIONS
    jsonRequest = JsonUtils.newObjectNode();
    // has queryOptions in brokerRequest already
    Map<String, String> queryOptions = new HashMap<>();
    queryOptions.put("queryOption1", "foo");
    brokerRequest.setQueryOptions(queryOptions);
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertEquals(brokerRequest.getQueryOptionsSize(), 1);
    Assert.assertEquals(brokerRequest.getQueryOptions().get("queryOption1"), "foo");
    // has queryOptions in query
    query = "select * from table option(queryOption1=foo)";
    brokerRequest = compiler.compileToBrokerRequest(query);
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertEquals(brokerRequest.getQueryOptionsSize(), 1);
    Assert.assertEquals(brokerRequest.getQueryOptions().get("queryOption1"), "foo");
    // has query options in json payload
    query = "select * from table";
    brokerRequest = compiler.compileToBrokerRequest(query);
    jsonRequest.put(Request.QUERY_OPTIONS, "queryOption1=foo");
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertEquals(brokerRequest.getQueryOptionsSize(), 1);
    Assert.assertEquals(brokerRequest.getQueryOptions().get("queryOption1"), "foo");
    // has query options in both, union. broker request takes priority
    query = "select * from table option(queryOption1=foo)";
    brokerRequest = compiler.compileToBrokerRequest(query);
    jsonRequest.put(Request.QUERY_OPTIONS, "queryOption1=bar;queryOption2=moo");
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertEquals(brokerRequest.getQueryOptionsSize(), 2);
    Assert.assertEquals(brokerRequest.getQueryOptions().get("queryOption1"), "foo");
    Assert.assertEquals(brokerRequest.getQueryOptions().get("queryOption2"), "moo");
    // has all 3
    query = "select * from table";
    jsonRequest = JsonUtils.newObjectNode();
    brokerRequest = compiler.compileToBrokerRequest(query);
    jsonRequest.put(Request.TRACE, true);
    jsonRequest.put(Request.DEBUG_OPTIONS, "debugOption1=foo");
    jsonRequest.put(Request.QUERY_OPTIONS, "queryOption1=bar;queryOption2=moo");
    BaseBrokerRequestHandler.setOptions(requestId, query, jsonRequest, brokerRequest);
    Assert.assertTrue(brokerRequest.isEnableTrace());
    Assert.assertEquals(brokerRequest.getDebugOptionsSize(), 1);
    Assert.assertEquals(brokerRequest.getDebugOptions().get("debugOption1"), "foo");
    Assert.assertEquals(brokerRequest.getQueryOptionsSize(), 2);
    Assert.assertEquals(brokerRequest.getQueryOptions().get("queryOption1"), "bar");
    Assert.assertEquals(brokerRequest.getQueryOptions().get("queryOption2"), "moo");
}

// Testing positive cases of flattening the query tree.
@Test
public void testPositive() throws Exception {
    Pql2Compiler pql2Compiler = new Pql2Compiler();
    BrokerRequest req;
    String timeColumn = null;
    FilterQueryTree tree;
    int numLeaves;
    int numOps;
    req = pql2Compiler.compileToBrokerRequest("SELECT * FROM T WHERE (A = 4 AND B = 5) AND (C=7)");
    tree = RequestUtils.generateFilterQueryTree(_optimizer.optimize(req, timeColumn));
    Assert.assertEquals(tree.getChildren().size(), 3);
    Assert.assertEquals(tree.getOperator(), FilterOperator.AND);
    for (FilterQueryTree node : tree.getChildren()) {
        Assert.assertNull(node.getChildren());
        Assert.assertEquals(node.getOperator(), FilterOperator.EQUALITY);
    }
    req = pql2Compiler.compileToBrokerRequest("SELECT * FROM T WHERE ((A = 4 AND B = 5) AND (C=7)) AND D=8");
    tree = RequestUtils.generateFilterQueryTree(_optimizer.optimize(req, timeColumn));
    Assert.assertEquals(tree.getChildren().size(), 4);
    Assert.assertEquals(tree.getOperator(), FilterOperator.AND);
    for (FilterQueryTree node : tree.getChildren()) {
        Assert.assertNull(node.getChildren());
        Assert.assertEquals(node.getOperator(), FilterOperator.EQUALITY);
    }
    req = pql2Compiler.compileToBrokerRequest("SELECT * FROM T WHERE (A = 4 OR B = 5) OR (C=7)");
    tree = RequestUtils.generateFilterQueryTree(_optimizer.optimize(req, timeColumn));
    Assert.assertEquals(tree.getChildren().size(), 3);
    Assert.assertEquals(tree.getOperator(), FilterOperator.OR);
    for (FilterQueryTree node : tree.getChildren()) {
        Assert.assertNull(node.getChildren());
        Assert.assertEquals(node.getOperator(), FilterOperator.EQUALITY);
    }
    req = pql2Compiler.compileToBrokerRequest("SELECT * FROM T WHERE ((A = 4 OR B = 5) OR (C=7)) OR D=8");
    tree = RequestUtils.generateFilterQueryTree(_optimizer.optimize(req, timeColumn));
    Assert.assertEquals(tree.getChildren().size(), 4);
    Assert.assertEquals(tree.getOperator(), FilterOperator.OR);
    for (FilterQueryTree node : tree.getChildren()) {
        Assert.assertNull(node.getChildren());
        Assert.assertEquals(node.getOperator(), FilterOperator.EQUALITY);
    }
    // 3-level test case
    req = pql2Compiler.compileToBrokerRequest("SELECT * FROM T WHERE ((A = 4 OR (B = 5 OR D = 9)) OR (C=7)) OR E=8");
    tree = RequestUtils.generateFilterQueryTree(_optimizer.optimize(req, timeColumn));
    Assert.assertEquals(tree.getChildren().size(), 5);
    Assert.assertEquals(tree.getOperator(), FilterOperator.OR);
    for (FilterQueryTree node : tree.getChildren()) {
        Assert.assertNull(node.getChildren());
        Assert.assertEquals(node.getOperator(), FilterOperator.EQUALITY);
    }
    // Mixed case.
    req = pql2Compiler.compileToBrokerRequest("SELECT * FROM T WHERE ((A = 4 OR (B = 5 AND D = 9)) OR (C=7)) OR E=8");
    tree = RequestUtils.generateFilterQueryTree(_optimizer.optimize(req, timeColumn));
    Assert.assertEquals(tree.getChildren().size(), 4);
    Assert.assertEquals(tree.getOperator(), FilterOperator.OR);
    numLeaves = 0;
    numOps = 0;
    for (FilterQueryTree node : tree.getChildren()) {
        if (node.getOperator().equals(FilterOperator.EQUALITY)) {
            Assert.assertNull(node.getChildren());
            numLeaves++;
        } else {
            Assert.assertNotNull(node.getChildren());
            Assert.assertEquals(node.getOperator(), FilterOperator.AND);
            numOps++;
        }
    }
    Assert.assertEquals(1, numOps);
    Assert.assertEquals(3, numLeaves);
    final int maxNodesAtTopLevel = FlattenNestedPredicatesFilterQueryTreeOptimizer.MAX_OPTIMIZING_DEPTH;
    String whereClause = constructWhereClause(FilterOperator.OR, maxNodesAtTopLevel + 50);
    req = pql2Compiler.compileToBrokerRequest("SELECT * FROM T WHERE " + whereClause);
    tree = RequestUtils.generateFilterQueryTree(_optimizer.optimize(req, timeColumn));
    Assert.assertEquals(tree.getChildren().size(), maxNodesAtTopLevel + 1);
    Assert.assertEquals(tree.getOperator(), FilterOperator.OR);
    numLeaves = 0;
    numOps = 0;
    for (FilterQueryTree node : tree.getChildren()) {
        if (node.getOperator().equals(FilterOperator.EQUALITY)) {
            Assert.assertNull(node.getChildren());
            numLeaves++;
        } else {
            Assert.assertNotNull(node.getChildren());
            numOps++;
        }
    }
    Assert.assertEquals(maxNodesAtTopLevel, numLeaves);
    Assert.assertEquals(1, numOps);
}

