    for (DataSchema.ColumnDataType columnDataType : new DataSchema.ColumnDataType[] { FLOAT_ARRAY, DOUBLE_ARRAY }) {
        Assert.assertFalse(columnDataType.isNumber());
        Assert.assertFalse(columnDataType.isWholeNumber());
