    InstanceAssignmentConfig offlineInstanceAssignmentConfig = new InstanceAssignmentConfig(new InstanceTagPoolConfig(TagNameUtils.getOfflineTagForTenant(TENANT_NAME), false, 0, null), null, new InstanceReplicaGroupPartitionConfig(false, 0, 0, 0, 0, 0));
