@Test
public void testCreateUpdateSchema() throws IOException {
    String schemaName = "testSchema";
    Schema schema = createDummySchema(schemaName);
    String url = _controllerRequestURLBuilder.forSchemaCreate();
    PostMethod postMethod = sendMultipartPostRequest(url, schema.toSingleLineJsonString());
    Assert.assertEquals(postMethod.getStatusCode(), 200);
    schema.addField(new DimensionFieldSpec("NewColumn", FieldSpec.DataType.STRING, true));
    postMethod = sendMultipartPostRequest(url, schema.toSingleLineJsonString());
    Assert.assertEquals(postMethod.getStatusCode(), 200);
    String schemaStr = sendGetRequest(_controllerRequestURLBuilder.forSchemaGet(schemaName));
    Schema readSchema = Schema.fromString(schemaStr);
    Schema inputSchema = Schema.fromString(schema.toSingleLineJsonString());
    Assert.assertEquals(readSchema, inputSchema);
    Assert.assertTrue(readSchema.getFieldSpecMap().containsKey("NewColumn"));
    final String yetAnotherColumn = "YetAnotherColumn";
    Assert.assertFalse(readSchema.getFieldSpecMap().containsKey(yetAnotherColumn));
    schema.addField(new DimensionFieldSpec(yetAnotherColumn, FieldSpec.DataType.STRING, true));
    PutMethod putMethod = sendMultipartPutRequest(_controllerRequestURLBuilder.forSchemaUpdate(schemaName), schema.toSingleLineJsonString());
    Assert.assertEquals(putMethod.getStatusCode(), 200);
    // verify some more...
    schemaStr = sendGetRequest(_controllerRequestURLBuilder.forSchemaGet(schemaName));
    readSchema = Schema.fromString(schemaStr);
    inputSchema = Schema.fromString(schema.toSingleLineJsonString());
    Assert.assertEquals(readSchema, inputSchema);
    Assert.assertTrue(readSchema.getFieldSpecMap().containsKey(yetAnotherColumn));
    // error cases
    putMethod = sendMultipartPutRequest(_controllerRequestURLBuilder.forSchemaUpdate(schemaName), schema.toSingleLineJsonString().substring(1));
    // invalid json
    Assert.assertEquals(putMethod.getStatusCode(), 400);
    schema.setSchemaName("differentSchemaName");
    putMethod = sendMultipartPutRequest(_controllerRequestURLBuilder.forSchemaUpdate(schemaName), schema.toSingleLineJsonString());
    Assert.assertEquals(putMethod.getStatusCode(), 400);
}

@Test
public void testSegmentCrcApi() throws Exception {
    // Adding table
    TableConfig tableConfig = new TableConfig.Builder(CommonConstants.Helix.TableType.OFFLINE).setTableName(TABLE_NAME).setNumReplicas(1).build();
    _helixResourceManager.addTable(tableConfig);
    // Wait for the table addition
    while (!_helixResourceManager.hasOfflineTable(TABLE_NAME)) {
        Thread.sleep(100);
    }
    // Check when there is no segment.
    Map<String, SegmentMetadata> segmentMetadataTable = new HashMap<>();
    checkCrcRequest(segmentMetadataTable, 0);
    // Upload Segments
    for (int i = 0; i < 5; ++i) {
        SegmentMetadata segmentMetadata = SegmentMetadataMockUtils.mockSegmentMetadata(TABLE_NAME);
        _helixResourceManager.addNewSegment(TABLE_NAME, segmentMetadata, "downloadUrl");
        segmentMetadataTable.put(segmentMetadata.getName(), segmentMetadata);
    }
    // Get crc info from API and check that they are correct.
    checkCrcRequest(segmentMetadataTable, 5);
    // Add more segments
    for (int i = 0; i < 5; ++i) {
        SegmentMetadata segmentMetadata = SegmentMetadataMockUtils.mockSegmentMetadata(TABLE_NAME);
        _helixResourceManager.addNewSegment(TABLE_NAME, segmentMetadata, "downloadUrl");
        segmentMetadataTable.put(segmentMetadata.getName(), segmentMetadata);
    }
    // Get crc info from API and check that they are correct.
    checkCrcRequest(segmentMetadataTable, 10);
    // Delete segments
    _helixResourceManager.deleteSegment(TableNameBuilder.OFFLINE.tableNameWithType(TABLE_NAME), segmentMetadataTable.values().iterator().next().getName());
    // Check crc api
    checkCrcRequest(segmentMetadataTable, 9);
}

@Test
public void testCreateTable() throws Exception {
    // Create an OFFLINE table with an invalid name which should fail
    // NOTE: Set bad table name inside table config builder is not allowed, so have to explicitly set in table config
    TableConfig offlineTableConfig = _offlineBuilder.build();
    offlineTableConfig.setTableName("bad__table__name");
    try {
        sendPostRequest(_createTableUrl, offlineTableConfig.toJsonConfigString());
