    FlushThresholdUpdater defaultFlushThresholdUpdater = flushThresholdUpdateManager.getFlushThresholdUpdater(mockStreamConfig(StreamConfig.DEFAULT_FLUSH_THRESHOLD_ROWS));
    assertTrue(defaultFlushThresholdUpdater instanceof DefaultFlushThresholdUpdater);
    assertEquals(((DefaultFlushThresholdUpdater) defaultFlushThresholdUpdater).getTableFlushSize(), StreamConfig.DEFAULT_FLUSH_THRESHOLD_ROWS);
    // Flush threshold rows set to 0 - SegmentSizeBasedFlushThresholdUpdater should be returned
