@Test
public void testRemoveDeletedSegments() throws Exception {
    PropertiesConfiguration pinotFSConfig = new PropertiesConfiguration();
    pinotFSConfig.addProperty(CommonConstants.Controller.PREFIX_OF_CONFIG_OF_PINOT_FS_FACTORY + ".class", LocalPinotFS.class.getName());
    PinotFSFactory.init(pinotFSConfig);
