        Assert.assertEquals(intermediateRecord._values[0], record.getValues()[0]);
        Assert.assertEquals(intermediateRecord._values[1], record.getValues()[4]);
    }
    // d2, sum(m1), d3
    sel1.setColumn("d2");
    sel2.setColumn("sum(m1)");
    sel3.setColumn("d3");
