@Test
public void testSlowPlanNode() {
    // Warning: this test is slow (take 10 seconds).
    AtomicBoolean notInterrupted = new AtomicBoolean();
    List<PlanNode> planNodes = new ArrayList<>();
    for (int i = 0; i < 20; i++) {
        planNodes.add(new PlanNode() {

            @Override
            public Operator run() {
                try {
                    Thread.sleep(20000);
                } catch (InterruptedException e) {
                    // Thread should be interrupted
                    throw new RuntimeException(e);
                }
                notInterrupted.set(true);
                return null;
            }

            @Override
            public void showTree(String prefix) {
            }
        });
    }
    CombinePlanNode combinePlanNode = new CombinePlanNode(planNodes, null, _executorService, 0, InstancePlanMakerImplV2.DEFAULT_NUM_GROUPS_LIMIT);
    try {
        combinePlanNode.run();
    } catch (RuntimeException e) {
        Assert.assertTrue(e.getCause() instanceof TimeoutException);
        Assert.assertFalse(notInterrupted.get());
        return;
    }
    // Fail.
    Assert.fail();
}

