                try (BaseMutableDictionary dictionary = makeOffHeapDictionary(EST_CARDINALITY, maxOverflowSize, dataType)) {
                    testMutableDictionary(dictionary, dataType);
                }
            }
        }
    } catch (Throwable t) {
        Assert.fail("Failed with random seed: " + RANDOM_SEED, t);
    }
}

