@Test
public void test() {
    // Query without time predicate
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE foo = 'bar'"));
    // Equality predicate
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time = 0"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time = 10"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time = 20"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time = 30"));
    // Range predicate
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time < 10"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time <= 10"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time >= 10"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time > 20"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time BETWEEN 20 AND 30"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time BETWEEN 30 AND 40"));
    // Invalid range predicate
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time BETWEEN 20 AND 10"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time BETWEEN 30 AND 20"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time BETWEEN 10 AND 10"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time BETWEEN 20 AND 20"));
    // AND operator
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time = 0 AND time > 10"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time > 0 AND time < 10"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time >= 0 AND time <= 10"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time > 20 AND time < 10"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time >= 20 AND time < 30"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time > 0 AND time BETWEEN 0 AND 10"));
    // OR operator
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time = 0 OR time > 10"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time = 0 OR time < 10"));
    Assert.assertFalse(runPruner("SELECT COUNT(*) FROM table WHERE time >= 0 OR time <= 10"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time > 30 OR time < 10"));
    Assert.assertTrue(runPruner("SELECT COUNT(*) FROM table WHERE time BETWEEN 0 AND 5 OR time BETWEEN 30 AND 35"));
}

@Test
public void testExtractExpressions() {
    // For non 'SELECT *' select only queries, should return deduplicated selection expressions
    List<String> selectionColumns = Arrays.asList("add(foo,'1')", "foo", "sub(bar,'2')", "bar", "foo", "foobar", "bar");
    IndexSegment indexSegment = mock(IndexSegment.class);
    when(indexSegment.getPhysicalColumnNames()).thenReturn(new HashSet<>(Arrays.asList("foo", "bar", "foobar")));
    List<TransformExpressionTree> expressions = SelectionOperatorUtils.extractExpressions(selectionColumns, indexSegment);
    assertEquals(expressions.size(), 5);
    assertEquals(expressions.get(0).toString(), "add(foo,'1')");
    assertEquals(expressions.get(1).toString(), "foo");
    assertEquals(expressions.get(2).toString(), "sub(bar,'2')");
    assertEquals(expressions.get(3).toString(), "bar");
    assertEquals(expressions.get(4).toString(), "foobar");
    // For 'SELECT *' select only queries, should return all physical columns in alphabetical order
    expressions = SelectionOperatorUtils.extractExpressions(Collections.singletonList("*"), indexSegment);
    assertEquals(expressions.size(), 3);
    assertEquals(expressions.get(0).toString(), "bar");
    assertEquals(expressions.get(1).toString(), "foo");
    assertEquals(expressions.get(2).toString(), "foobar");
    // For non 'SELECT *' select order-by queries, should return deduplicated order-by expressions followed by selection
    // expressions
    SelectionSort selectionSort1 = new SelectionSort();
    selectionSort1.setColumn("foo");
    SelectionSort selectionSort2 = new SelectionSort();
    selectionSort2.setColumn("sub(bar,'2')");
    List<SelectionSort> sortSequence = Arrays.asList(selectionSort1, selectionSort2);
    expressions = SelectionOperatorUtils.extractExpressions(selectionColumns, indexSegment, sortSequence);
    assertEquals(expressions.size(), 5);
    assertEquals(expressions.get(0).toString(), "foo");
    assertEquals(expressions.get(1).toString(), "sub(bar,'2')");
    assertEquals(expressions.get(2).toString(), "add(foo,'1')");
    assertEquals(expressions.get(3).toString(), "bar");
    assertEquals(expressions.get(4).toString(), "foobar");
    // For 'SELECT *' select order-by queries, should return deduplicated order-by expressions followed by all physical
    // columns in alphabetical order
    expressions = SelectionOperatorUtils.extractExpressions(Collections.singletonList("*"), indexSegment, sortSequence);
    assertEquals(expressions.size(), 4);
    assertEquals(expressions.get(0).toString(), "foo");
    assertEquals(expressions.get(1).toString(), "sub(bar,'2')");
    assertEquals(expressions.get(2).toString(), "bar");
    assertEquals(expressions.get(3).toString(), "foobar");
}

