    assertEquals(selectionResults.size(), 10);
    for (int i = 0; i < 10; i++) {
        assertEquals(Integer.parseInt(selectionResults.get(i).get(0).textValue()), i);
    }
    // Selection order-by
    query = "SELECT mapValue(stringKeyMap__KEYS, 'k2', stringKeyMap__VALUES) FROM " + getTableName() + " ORDER BY mapValue(stringKeyMap__KEYS, 'k1', stringKeyMap__VALUES)";
    pinotResponse = postQuery(query);
