public void testLongGroupByPeriod() {
    LongSeries in = LongSeries.buildFrom(parseDateMillis("2018-01-01 00:00:00 PST"), parseDateMillis("2018-01-01 03:00:00 PST"), parseDateMillis("2018-01-01 06:00:00 PST"), parseDateMillis("2018-01-01 09:00:00 PST"), parseDateMillis("2018-01-01 12:00:00 PST"), parseDateMillis("2018-01-01 15:00:00 PST"), parseDateMillis("2018-01-01 18:00:00 PST"), parseDateMillis("2018-01-01 21:00:00 PST"), parseDateMillis("2018-01-02 00:00:00 PST"));
    // timestamps with timezone
    Grouping.SeriesGrouping grouping = in.groupByPeriod(DateTimeZone.forID("America/Los_Angeles"), Period.hours(6));
    Assert.assertEquals(grouping.size(), 5);
    assertEquals(grouping.count().getValues().getLongs(), 2, 2, 2, 2, 1);
    // timestamps from (truncating) origin
    Grouping.SeriesGrouping groupingOffset = in.groupByPeriod(parseDate("2018-01-01 02:00:00 PST"), Period.hours(6));
