    assertEquals(groupingOffset.count().getValues().getLongs(), 2, 2, 2, 2);
}

@Test
public void testLongGroupByPeriodDaylightSavingsTime() {
    LongSeries in = LongSeries.buildFrom(parseDateMillis("2018-03-11 01:30:00 PST"), parseDateMillis("2018-03-11 03:00:00 PDT"), parseDateMillis("2018-03-11 04:00:00 PDT"), // 1 day later
