    DataFrame out = df.slice("one");
    Assert.assertEquals(out.size(), 4);
    Assert.assertEquals(out.getSeriesNames().size(), 1);
    Assert.assertFalse(out.hasIndex());
    assertEquals(out.getLongs("one"), 1, 2, 3, 4);
}

