    rightOperators = ConfigUtils.getMap(rightOperators.get(PROP_RIGHT_OP));
    Assert.assertEquals(leftOperators.get(PROP_VALUE), "entityC");
    Assert.assertEquals(rightOperators.get(PROP_VALUE), "entityD");
}

