    spec.setBaselineAggregates(ImmutableMap.of(MetricSlice.from(1, 3000, 3600), 100.0));
    spec.setBaselineTimeseries(ImmutableMap.of(MetricSlice.from(1, 3000, 3600), TimeSeries.fromDataFrame(DataFrame.builder(COL_TIME + ":LONG", COL_VALUE + ":DOUBLE", COL_UPPER_BOUND + ":DOUBLE", COL_LOWER_BOUND + ":DOUBLE").append(3000, 100, 200, 50).build())));
    InputDataFetcher dataFetcher = new DefaultInputDataFetcher(provider, this.config.getId());
