    Multimap<String, String> filters = ArrayListMultimap.create();
    filters.put("c", "d");
    filters.put("a", "b");
    List<String> encoded = EntityUtils.encodeDimensions(filters);
    Assert.assertEquals(encoded.size(), 2);
    Assert.assertEquals(encoded.get(0), "a%3Db");
    Assert.assertEquals(encoded.get(1), "c%3Dd");
}

@Test
public void testEncodeDimensionsMultiKeyMultiValueSorting() {
    Multimap<String, String> filters = ArrayListMultimap.create();
    filters.put("c", "d");
    filters.put("a", "b");
    filters.put("c", "e");
    List<String> encoded = EntityUtils.encodeDimensions(filters);
    Assert.assertEquals(encoded.size(), 3);
    Assert.assertEquals(encoded.get(0), "a%3Db");
    Assert.assertEquals(encoded.get(1), "c%3Dd");
    Assert.assertEquals(encoded.get(2), "c%3De");
}

@Test
public void testEncodeDimensionsExclusions() {
    Multimap<String, String> filters = ArrayListMultimap.create();
    filters.put("a", "A");
    filters.put("b", "!B");
    filters.put("c", "<C");
    filters.put("d", ">D");
    filters.put("e", "<=E");
    filters.put("f", ">=F");
    List<String> encoded = EntityUtils.encodeDimensions(filters);
    Assert.assertEquals(encoded.size(), 6);
    Assert.assertEquals(encoded.get(0), "a%3DA");
    Assert.assertEquals(encoded.get(1), "b!%3DB");
    Assert.assertEquals(encoded.get(2), "c%3CC");
    Assert.assertEquals(encoded.get(3), "d%3ED");
    Assert.assertEquals(encoded.get(4), "e%3C%3DE");
    Assert.assertEquals(encoded.get(5), "f%3E%3DF");
}

@Test
public void testEncodeDimensionsNonExclusions() {
    Multimap<String, String> filters = ArrayListMultimap.create();
    filters.put("a", "xA");
    filters.put("b", "x!B");
    filters.put("c", "x<C");
    filters.put("d", "x>D");
    filters.put("e", "x<=E");
    filters.put("f", "x>=F");
    List<String> encoded = EntityUtils.encodeDimensions(filters);
    Assert.assertEquals(encoded.size(), 6);
    Assert.assertEquals(encoded.get(0), "a%3DxA");
    Assert.assertEquals(encoded.get(1), "b%3Dx!B");
    Assert.assertEquals(encoded.get(2), "c%3Dx%3CC");
    Assert.assertEquals(encoded.get(3), "d%3Dx%3ED");
    Assert.assertEquals(encoded.get(4), "e%3Dx%3C%3DE");
    Assert.assertEquals(encoded.get(5), "f%3Dx%3E%3DF");
}

@Test
public void testLinearTimeRangeStrategy() {
    ScoreUtils.TimeRangeStrategy scorer = new ScoreUtils.LinearStartTimeStrategy(10, 20);
    Assert.assertEquals(scorer.score(9, -1), 0.0d, EPSILON);
    Assert.assertEquals(scorer.score(10, -1), 1.0d, EPSILON);
    Assert.assertEquals(scorer.score(19, -1), 0.1d, EPSILON);
    Assert.assertEquals(scorer.score(20, -1), 0.0d, EPSILON);
    Assert.assertEquals(scorer.score(99, -1), 0.0d, EPSILON);
}

@Test
public void testTriangularTimeRangeStrategy() {
    ScoreUtils.TimeRangeStrategy scorer = new ScoreUtils.TriangularStartTimeStrategy(10, 20, 40);
    Assert.assertEquals(scorer.score(9, -1), 0.0d, EPSILON);
    Assert.assertEquals(scorer.score(10, -1), 0.0d, EPSILON);
    Assert.assertEquals(scorer.score(19, -1), 0.9d, EPSILON);
    Assert.assertEquals(scorer.score(20, -1), 1.0d, EPSILON);
    Assert.assertEquals(scorer.score(30, -1), 0.5d, EPSILON);
    Assert.assertEquals(scorer.score(39, -1), 0.05d, EPSILON);
    Assert.assertEquals(scorer.score(40, -1), 0.0d, EPSILON);
    Assert.assertEquals(scorer.score(99, -1), 0.0d, EPSILON);
}

@Test
public void testQuadraticTriangularTimeRangeStrategy() {
    ScoreUtils.TimeRangeStrategy scorer = new ScoreUtils.QuadraticTriangularStartTimeStrategy(10, 20, 40);
    Assert.assertEquals(scorer.score(9, -1), 0.0d, EPSILON);
